package com.bank.matching.repository;

import com.bank.matching.model.TradeOrder;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import jakarta.persistence.LockModeType;
import java.math.BigDecimal;
import java.util.Optional;

public interface OrderRepository extends JpaRepository<TradeOrder, String> {

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("""
        SELECT o FROM TradeOrder o
        WHERE o.symbol = :symbol AND o.side = :oppositeSide
        AND o.quantity = :quantity AND o.price = :price
        AND o.status = 'PENDING'
        ORDER BY o.createdAt ASC
        """)
    Optional<TradeOrder> findMatchingOrder(String symbol, String oppositeSide,
                                            int quantity, BigDecimal price);
}
