import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;
import java.math.BigDecimal;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Service
@RequiredArgsConstructor
@Slf4j
public class ExchangePriceService {

    private final RestClient exchangeRestClient;

    // Thread-safe cache: ConcurrentHashMap for shared mutable state
    private final Map<String, BigDecimal> priceCache = new ConcurrentHashMap<>();

    public BigDecimal getLatestPrice(String symbol) {
        // Check cache first (thread-safe — ConcurrentHashMap)
        BigDecimal cached = priceCache.get(symbol);
        if (cached != null) {
            log.debug("Price cache hit for {}: Rs.{}", symbol, cached);
            return cached;
        }

        // Fetch from exchange (RestClient has connect + read timeout configured)
        log.info("Fetching live price for {} from exchange", symbol);
        try {
            // Simplified — real app would deserialize JSON response
            BigDecimal price = new BigDecimal("2450.50"); // simulated
            priceCache.put(symbol, price);
            return price;
        } catch (Exception e) {
            log.error("Exchange price fetch failed for {}: {}", symbol, e.getMessage());
            throw new RuntimeException("Exchange unreachable for " + symbol, e);
        }
    }
