import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class OrderMatchingServiceTest {

    @Mock OrderRepository orderRepo;
    @Mock ExchangePriceService priceService;
    @InjectMocks OrderMatchingService matchingService;

    @Test
    void shouldMatchBuyWithExistingSellOrder() {
        TradeOrder existingSell = new TradeOrder("ORD-SELL", "CUR3001", "RELIANCE",
            "SELL", 100, new BigDecimal("2450.00"));

        when(orderRepo.save(any(TradeOrder.class))).thenAnswer(i -> i.getArgument(0));
        when(orderRepo.findMatchingOrder("RELIANCE", "SELL", 100, new BigDecimal("2450.00")))
            .thenReturn(Optional.of(existingSell));

        OrderResponse response = matchingService.placeOrder(
            new OrderRequest("SAV2001", "RELIANCE", "BUY", 100, new BigDecimal("2450.00")));

        assertThat(response.status()).isEqualTo("MATCHED");
        assertThat(response.matchedWith()).isEqualTo("ORD-SELL");
        verify(orderRepo, times(3)).save(any(TradeOrder.class)); // new + 2 matched updates
    }

    @Test
    void shouldQueueOrderWhenNoMatchExists() {
        when(orderRepo.save(any(TradeOrder.class))).thenAnswer(i -> i.getArgument(0));
        when(orderRepo.findMatchingOrder(anyString(), anyString(), anyInt(), any()))
            .thenReturn(Optional.empty());

        OrderResponse response = matchingService.placeOrder(
            new OrderRequest("SAV2001", "RELIANCE", "BUY", 100, new BigDecimal("2450.00")));

        assertThat(response.status()).isEqualTo("PENDING");
        assertThat(response.matchedWith()).isNull();
    }
}
